// One-shot pulse generator, used to go from the "counting" state to the
// "waiting for ack" state. Triggers once per 1000 cycles, regardless of
// the value of the counter.
module OneShotPulse (
    input clk,
    input reset,
    input go,
    output reg pulse
);
    reg [9:0] counter;
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
            pulse <= 0;
        end else begin
            counter <= counter + 1;
            if (counter == 999) pulse <= 1;
            if (go) begin
                counter <= 0;
                pulse <= 0;
            end
        end
    end
endmodule

