// Timer that starts counting on a specific input pattern, determines the
// duration to delay, waits for the counters to finish counting, and notifies
// the user after the delay has passed. The user must acknowledge the timer
// to restart the cycle.
module TopModule (
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [3:0] delay;
    reg [15:0] counter;
    reg [1:0] state;
    reg [1:0] next_state;
    reg [3:0] remaining;
    reg [3:0] next_remaining;
    reg [15:0] next_counter;
    reg [3:0] next_count;
    reg next_counting;
    reg next_done;

    // State machine
    always @(*) begin
        case (state)
            2'b00: begin
                if (data && !delay[0] && !delay[1] && delay[2] && delay[3])
                    next_state = 2'b01;
                else
                    next_state = 2'b00;
            end
            2'b01: begin
                next_state = 2'b10;
            end
            2'b10: begin
                if (counter == 15999)
                    next_state = 2'b11;
                else
                    next_state = 2'b10;
            end
            2'b11: begin
                if (ack)
                    next_state = 2'b00;
                else
                    next_state = 2'b11;
            end
        endcase
    end

    // Counter
    always @(posedge clk) begin
        if (reset)
            counter <= 16'd0;
        else if (state == 2'b10)
            counter <= counter + 1;
        else
            counter <= 16'd0;
    end

    // Delay register
    always @(posedge clk) begin
        if (reset)
            delay <= 4'd0;
        else if (state == 2'b00 && data && !delay[0] && !delay[1] && delay[2] && delay[3])
            delay <= {data, data, data, data};
    end

    // Remaining counter
    always @(posedge clk) begin
        if (reset)
            remaining <= 4'd0;
        else if (state == 2'b10) begin
            if (counter % 1000 == 0)
                remaining <= remaining - 1;
        end
    end

    // Count register
    always @(posedge clk) begin
        if (reset)
            count <= 4'd0;
        else if (state == 2'b10) begin
            if (counter % 1000 == 0)
                count <= count + 1;
        }
    end

    // Counting register
    always @(posedge clk) begin
        if (reset)
            counting <= 1'b0;
        else if (state == 2'b01)
            counting <= 1'b1;
        else if (state == 2'b10)
            counting <= 1'b1;
        else
            counting <= 1'b0;
    end

    // Done register
    always @(posedge clk) begin
        if (reset)
            done <= 1'b0;
        else if (state == 2'b11)
            done <= 1'b1;
        else
            done <= 1'b0;
    end

    // Register updates
    always @(posedge clk) begin
        if (reset)
            state <= 2'b00;
        else
            state <= next_state;
        counter <= next_counter;
        delay <= {data, data, data, data};
        count <= next_count;
        counting <= next_counting;
        done <= next_done;
    end
