// One-bit up-down counter, modulo 1000. Outputs a count that is 1000 more
// than the input when the up-down switch is in high-to-low transition.
module Counter1000 (
    input clk,
    input reset,
    input updown,
    output reg [2:0] count
);
    always @(posedge clk) begin
        if (reset) count <= 3'd0;
        else if (updown) count <= count + 1;
        else count <= count - 1;
    end
endmodule

