    input  data,
    output reg [3:0] count,
    output reg        counting,
    output reg        done,
    input  ack
);
    reg [3:0] delay;
    reg [15:0] counter;
    reg [3:0] state;
    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            counter <= 0;
