    always @(posedge clk) delayed_data_3 <= delayed_data_2;
    always @(posedge clk) delayed_data_4 <= delayed_data_3;
    assign pattern = (delayed_data_4 == 1'b1) && (delayed_data_3 == 1'b1) && (delayed_data_2 == 1'b0) && (delayed_data == 1'b1);
