// Timer with one input that counts for exactly (delay[3:0] + 1) * 1000 clock
// cycles, and notifies the user when this time is up. The duration of the
// delay is determined by the next 4 bits sent serially on the data input,
// most-significant-bit first.
module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [3:0] delay;
    reg [15:0] counter;
    reg [1:0] state;
    reg [1:0] next_state;
    reg [15:0] target;
    wire count_up;
    wire count_down;
    wire [15:0] remaining;
    wire [15:0] target_minus_counter;
    wire [3:0] count_next;
    wire [15:0] counter_next;
    reg [1:0] state_next;
    reg [3:0] count_reg;
    reg [15:0] counter_reg;
    reg counting_reg;
    reg done_reg;
    wire [3:0] count_plus_one;
    wire [3:0] count_minus_one;

    assign count_up = (state == 2'b00);
    assign count_down = (state == 2'b01);
    assign remaining = target - counter;
    assign target_minus_counter = target - counter_reg;
    assign count_next = count_up ? count_plus_one : count_minus_one;
    assign counter_next = count_up ? counter + 1 : counter - 1;

    always @(*) begin
        case (state)
            2'b00: next_state = 2'b01;
            2'b01: next_state = (counter_reg == 15) ? 2'b10 : 2'b00;
            2'b10: next_state = (ack) ? 2'b00 : 2'b10;
            default: next_state = 2'b00;
        endcase
    end

    always @(*) begin
        if (count_up) count_plus_one = count + 1;
        else count_plus_one = count;
        if (count_down) count_minus_one = count - 1;
        else count_minus_one = count;
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            delay <= 4'd0;
            counter <= 16'd0;
            count <= 4'd0;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            state <= next_state;
            case (state)
                2'b00: begin // Search for start pattern (1101).
                    if (data && !counting) begin
                        if (delay == 4'd14) begin
                            state <= 2'b01;
                            counter <= 16'd0;
                        end
                        delay <= delay + 1;
                    end else delay <= 4'd0;
                end
                2'b01: begin // Wait for the counters to finish counting.
                    if (counter == 15) state <= 2'b10;
                    else counter <= counter + 1;
                end
                2'b10: begin // Notify the user and wait for the ack.
                    done <= 1'b1;
                    if (ack) begin
                        state <= 2'b00;
                        delay <= 4'd0;
                        counter <= 16'd0;
                        count <= 4'd0;
                        counting <= 1'b0;
                        done <= 1'b0;
                    end
                end
            endcase
            count <= count_next;
            counter_reg <= counter_next;
            counting_reg <= (state == 2'b01);
            done_reg <= (state == 2'b10);
        end
    end

    assign counting = counting_reg;
    assign done = done_reg;

