// State machine states
`define ST_IDLE 2'd0
`define ST_DELAY1 2'd1
`define ST_DELAY2 2'd2
`define ST_DELAY3 2'd3
`define ST_DELAY4 2'd4
`define ST_COUNTING 2'd5

module TopModule (
    input clk,
    input reset,
    input data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input ack
);
    reg [1:0] state;
    reg [3:0] delay;
    reg [15:0] counter;
    reg [1:0] seq;
    always @(posedge clk) begin
        if (reset) begin
            state <= `ST_IDLE;
            delay <= 4'd0;
            counter <= 16'd0;
            seq <= 2'd0;
            count <= 4'd0;
            counting <= 1'd0;
            done <= 1'd0;
        end else begin
            case (state)
                `ST_IDLE: begin
                    if (data) seq <= seq + 1'd1;
                    if (seq == 2'd3 && data) begin
                        seq <= 2'd0;
                        state <= `ST_DELAY1;
                    end
                end
                `ST_DELAY1: begin
                    delay <= {data, delay[3:1]};
                    state <= `ST_DELAY2;
                end
                `ST_DELAY2: begin
                    delay <= {data, delay[3:1]};
                    state <= `ST_DELAY3;
                end
                `ST_DELAY3: begin
                    delay <= {data, delay[3:1]};
                    state <= `ST_DELAY4;
                end
                `ST_DELAY4: begin
                    delay <= {data, delay[3:1]};
                    counter <= 16'd0;
                    state <= `ST_COUNTING;
                    counting <= 1'd1;
                end
                `ST_COUNTING: begin
                    counter <= counter + 16'd1;
                    if (counter == (delay + 1) * 1000) begin
                        state <= `ST_IDLE;
                        counting <= 1'd0;
                        done <= 1'd1;
                    end else begin
                        count <= 4'd0;
                        for (int i=0; i<1000; i=i+1) begin
                            if (counter == (delay + 1 - i) * 1000) begin
                                count <= i;
                            end
                        end
                    end
                end
            endcase
            if (state == `ST_COUNTING && ack) done <= 1'd0;
        end
    end
endmodule

