// One-shot trigger
module one_shot(
    input  clk,
    input  reset,
    input  trigger,
    output reg pulse
);
    reg trigger_d1;
    always @(posedge clk) begin
        if (reset) begin
            trigger_d1 <= 1'b0;
            pulse <= 1'b0;
        end else begin
            trigger_d1 <= trigger;
            pulse <= trigger & ~trigger_d1;
        end
    end
endmodule

