// Implement a timer with a start signal and delay determined by a
// 4-bit counter, counting up to (delay+1)*1000 cycles, then counting
// down until the counter hits 0, and then resetting back to the start
// state and waiting for the start signal.
module TopModule(
    input  clk,
    input  reset,
    input  data,
    output reg [3:0] count,
    output reg counting,
    output reg done,
    input  ack
);
    reg [3:0] delay;
    reg [15:0] ticks;
    reg [1:0] state;
    reg [1:0] next_state;
    reg [3:0] count_up;
    wire count_done = ticks == 1000;
    wire [3:0] count_down = count_done ? count - 1 : count;
    wire [3:0] count_func = counting ? count_down : count_up;
    always @(*) begin
        next_state = state;
        case (state)
            2'd0: if (data && !counting) next_state = 2'd1;
            2'd1: if (!data) next_state = 2'd2;
            2'd2: if (data) next_state = 2'd3;
            2'd3: if (!data) next_state = 2'd4;
            2'd4: if (data) next_state = 2'd5;
            2'd5: if (!data) next_state = 2'd6;
            2'd6: if (data) next_state = 2'd7;
            2'd7: if (!data) next_state = 2'd0;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'd0;
            count <= 4'd0;
            delay <= 4'd0;
            ticks <= 16'd0;
            counting <= 1'b0;
            done <= 1'b0;
        end else begin
            state <= next_state;
            if (count_done) ticks <= 16'd0;
            else ticks <= ticks + 16'd1;
            if (state == 2'd7 && ack) done <= 1'b0;
            if (count_done && !ack) done <= 1'b1;
            if (state == 2'd7 && ack) begin
                count <= 4'd0;
                delay <= 4'd0;
                ticks <= 16'd0;
                counting <= 1'b0;
            end
            if (state == 2'd7 && ack) state <= 2'd0;
            if (state == 2'd7) count <= count_func;
            else count <= count_up;
            if (state == 2'd7) counting <= 1'b0;
            else if (count_done) counting <= 1'b0;
            else counting <= 1'b1;
            if (state == 2'd7) count_up <= 4'd0;
            else count_up <= count_up + 4'd1;
            if (state == 2'd7) delay <= 4'd0;
            else if (count_done) delay <= delay - 4'd1;
            if (state == 2'd7) state <= 2'd0;
        end
    end
endmodule

